<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php';require_once __DIR__.'/read-model.php';require_once __DIR__.'/campaign-store.php';
try{kalite_filo_admin_require_method('PATCH');kalite_filo_admin_require_same_origin();kalite_filo_admin_start_session();kalite_filo_admin_require_authentication();kalite_filo_admin_require_csrf();kalite_filo_admin_require_roles(['owner','admin','marketing']);$id=(string)($_GET['id']??'');if(preg_match('/^campaign-[a-f0-9]{12}$/',$id)!==1)throw new InvalidArgumentException('Invalid campaign id.');$body=kalite_filo_admin_read_json(262144);$lock=kalite_filo_admin_lock_campaign_store();try{$records=kalite_filo_admin_campaign_records();$found=false;foreach($records as &$record)if(($record['id']??'')===$id){$record=kalite_filo_admin_freeze_campaign_references(kalite_filo_admin_normalize_campaign($body,$record),kalite_filo_admin_content_snapshot());$campaign=$record;$found=true;break;}unset($record);if(!$found)kalite_filo_admin_json(['error'=>'not_found'],404);kalite_filo_admin_write_campaign_records($records);}finally{kalite_filo_admin_unlock_campaign_store($lock);}kalite_filo_admin_audit('campaign_update','success',['id'=>$id]);kalite_filo_admin_json(['campaign'=>$campaign]);}catch(InvalidArgumentException $e){kalite_filo_admin_json(['error'=>'validation_failed'],422);}catch(Throwable $e){error_log('Campaign failed: '.$e->getMessage());kalite_filo_admin_json(['error'=>'service_unavailable'],503);}
